head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vCurrPageNo = 1; // 현재 선택된 페이지번호
scwin.gLdMktTp = $c.stf.getUserInfo($p, "market");
scwin.gBondYn = $c.stf.getUserInfo($p, "bondYn");

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 코드 세팅·화면 초기화 후 게시판 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.setCode();
        scwin.initPage();
        scwin.listDsclBbs();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 이벤트 — 현재 별도 처리 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name sbx_PeriodTp_onchange
 * @description 기간선택 콤보 변경 이벤트 — 선택한 기간구분값으로 조회 시작일·종료일을 세팅한다.
 * @param {Object} info 변경 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbx_PeriodTp_onchange(info);
 */
scwin.sbx_PeriodTp_onchange = function (info) {
    try {
        const vTp = sbx_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, ica_SDATE, ica_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.sbx_PeriodTp_onchange" });
    }
};

/**
 * @method
 * @name sbx_PerPage_onchange
 * @description 페이지당 건수 콤보 변경 이벤트 — 현재 페이지번호를 1로 초기화한다.
 * @param {Object} info 변경 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbx_PerPage_onchange(info);
 */
scwin.sbx_PerPage_onchange = function (info) {
    try {
        scwin.vCurrPageNo = 1;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.sbx_PerPage_onchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 조회 버튼 클릭 이벤트 — 검색조건으로 게시판 목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Search_onclick(e);
 */
scwin.btn_Search_onclick = function (e) {
    try {
        scwin.listDsclBbs();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_oncelldblclick
 * @description 그리드 셀 더블클릭 이벤트 — 제목 컬럼이면 제도해설등 조회 팝업을 띄운다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_Grid_oncelldblclick(rowIndex, columnIndex, columnId);
 */
scwin.grd_Grid_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.readDsclBbs(rowIndex, columnId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.grd_Grid_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 신규 버튼 클릭 이벤트 — 제도해설등 신규 팝업을 띄운다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_New_onclick(e);
 */
scwin.btn_New_onclick = function (e) {
    try {
        scwin.new();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30402.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name sbm_Select_submitdone
 * @description 게시판 목록조회 submission 완료 — 첫 페이지면 총건수·페이지리스트를 세팅하고, 아니면 그리드 시작 행번호만 갱신한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_Select_submitdone(e);
 */
scwin.sbm_Select_submitdone = function (e) {
    if (!e.responseJSON.success) {
        return;
    }

    if (e.responseJSON.body.page === 1) {
        scwin.pageCount = $c.num.ceil(e.responseJSON.body.totalCount / sbx_PerPage.getValue());
        pgl_list.setCount(scwin.pageCount);
        tbx_totalCnt.setValue($c.num.formatNumber(e.responseJSON.body.totalCount));
        grd_Grid.setStartRowNumber(0);
    } else {
        const startIdx = (scwin.vPAGENO - 1) * sbx_PerPage.getValue();
        grd_Grid.setStartRowNumber(startIdx);
    }

    grd_Grid.setFocusedCell(0, 0);
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name initPage
 * @description 화면 초기화 — 조회기간을 기본 6개월로 세팅하고, 사용자 시장구분(채권상장팀이면 채권)과 시장구분 영역 표시 여부를 세팅한다.
 * @returns {void}
 * @hidden N
 * @example scwin.initPage();
 */
scwin.initPage = function () {
    // code default value setting
    // 1. 날짜 기본 6개월.
    const ToDay = $c.date.getServerDateTime();
    ica_EDATE.setValue(ToDay);
    const vSDATE = $c.date.addDate(ToDay, -6);
    ica_SDATE.setValue(vSDATE);
    rdo_mkt_gubun.setValue(scwin.gLdMktTp);

    if (scwin.gBondYn === 'Y') {
        rdo_mkt_gubun.setValue("4");
    }

    if (scwin.gLdMktTp === "9") {
        grp_mkt_gubun.show("");
    } else {
        grp_mkt_gubun.hide();
    }
};

/**
 * @method
 * @name listDsclBbs
 * @description 검색조건(시장구분·키워드·기간·등록자·메뉴구분·페이지 정보)으로 게시판 목록을 조회한다. 자료실 포함여부는 관리자일 때만 표시(PDS=Y).
 * @returns {void}
 * @hidden N
 * @example scwin.listDsclBbs();
 */
scwin.listDsclBbs = function () {
    let url = "/IntegratedBBS.do?method=listDsclBbs";
    url += "&MKT_ID=" + rdo_mkt_gubun.getValue();
    url += "&KEYWORD_FLAG=" + sbx_KEYWORD.getValue();
    url += "&KEYWORD=" + ibx_KEYWORD.getValue();
    url += "&SDATE=" + ica_SDATE.getValue();
    url += "&EDATE=" + ica_EDATE.getValue();
    url += "&EMP_NM=" + ibx_EMP_NM.getValue();
    url += "&MENU_FLAG=" + sbx_MENU_FLAG.getValue();
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + sbx_PerPage.getValue();
    url += "&PDS=Y"; // 자료실 포함여부.(관리자일때만 자료실을 표시함.)

    $c.sbm.setAction(sbm_Select, url);
    $c.sbm.execute(sbm_Select);
};

/**
 * @method
 * @name setCode
 * @description 코드 세팅 — 페이지당 건수 콤보(sbx_PerPage)에 공통코드 데이터를 세팅한다.
 * @returns {void}
 * @hidden N
 * @example scwin.setCode();
 */
scwin.setCode = function () {
    $c.stf.comboCbDataSet(sbx_PerPage);
};

/**
 * @method
 * @name readDsclBbs
 * @description 제목 컬럼 더블클릭 시 선택 행의 게시물ID로 제도해설등 조회 팝업을 오픈한다.
 * @param {Number} row 선택 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.readDsclBbs(row, colid);
 */
scwin.readDsclBbs = function (row, colid) {
    if (colid === "title") {
        const CONTN_ID = dlt_Grid.getCellData(row, "contnId");
        const param = { contnId: CONTN_ID };

        const opts = {
            width: 1000,
            height: 830,
            frameModal: "top",
        };

        frame.CreateDialogFrame("INTEBBS_READ", "/ui/dis/dsclinfo/ULDSTF30403.xml", "제도해설등 조회", opts, param);
    }
};

/**
 * @method
 * @name new
 * @description 제도해설등 신규 등록 팝업을 오픈한다.
 * @returns {void}
 * @hidden N
 * @example scwin.new();
 */
scwin.new = function () {
    const param = null;

    const opts = {
        width: 1000,
        height: 830,
        frameModal: "top",
    };

    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    $c.frame.CreateDialogFrame("INTEBBS_NEW", "/ui/dis/dsclinfo/ULDSTF30403.xml", "제도해설등 신규", opts, param);
};
